/**
 * Zod twins of the execution records in
 * `services/langgraph/agency/execution/models.py` (Python is the reference).
 *
 * Every schema is strict (Pydantic `extra="forbid"`) and its output is frozen
 * (`frozen=True`; top level only, as `Object.freeze` is shallow). Parsing returns
 * exactly Python's `model_dump(mode="json")`, defaults included; datetimes come
 * back as Pydantic's JSON text (see `datetime.ts`). `canonicalRecordHash` equals
 * Python's `canonical_hash(model)`. `tests/fixtures/execution-models.json` is
 * generated by `services/langgraph/tests/test_execution_models_parity_fixture.py`.
 *
 * Deliberate differences, each pinned by a fixture case:
 * - Pydantic's lax coercions are refused: numeric strings or booleans for numbers,
 *   `"yes"`/`"1"`/`0`/`1` for booleans, and unix timestamps for datetimes. Python
 *   accepts them; this twin fails closed instead of guessing.
 * - Integers beyond 2^53 (valid Python ints) are refused, as JS numbers lose them.
 * - Float fields are hashed as floats (`CanonicalFloat`), as Python stores `1` as
 *   `1.0` there. Integral floats *inside* `Any` fields (`expected_postcondition`,
 *   `observed_postcondition`) cannot be told from ints in JS: the caller must wrap
 *   them in `CanonicalFloat` to reproduce Python's hash.
 * - `ApprovalBinding` here is the execution-plane binding; `@amc/shared` has
 *   unrelated schemas of the same name (VNEXUS directions) and API-row variants
 *   of the receipts (extra run/tenant/project keys, not strict), so none is reused.
 */
import { z } from 'zod';
import { CanonicalFloat, CanonicalizationError, canonicalHash, type CanonicalValue } from '@amc/canonical';
import { DateTimeError, normalizeDateTime, utcNow } from './datetime';

export { DateTimeError, normalizeDateTime, utcNow } from './datetime';

export const NOT_MEASURED = 'NOT_MEASURED';

export const ArtifactLifecycleSchema = z.enum(['DRAFT', 'REVIEW_REQUIRED', 'VALIDATED', 'APPROVED', 'RELEASED', 'INVALIDATED']);
export const DependencyImpactSchema = z.enum(['UNAFFECTED', 'REVIEW_REQUIRED', 'STALE', 'REBUILD_REQUIRED']);
export const DependencyPolicySchema = z.enum(['HARD', 'SOFT']);
export const SemanticChangeSchema = z.enum(['NONE', 'COMPATIBLE', 'BREAKING', 'UNKNOWN']);
export const ApprovalStatusSchema = z.enum(['PENDING', 'APPROVED', 'REJECTED', 'STALE']);
export const WorkOrderStateSchema = z.enum([
  'PLANNED', 'READY', 'RUNNING', 'BLOCKED', 'SUCCEEDED', 'FAILED', 'ESCALATED', 'INVESTIGATION_REQUIRED',
]);
export const CriterionStatusSchema = z.enum(['SATISFIED', 'UNSATISFIED', 'STALE', 'BLOCKED', 'NOT_APPLICABLE']);

const hash64 = z.string().regex(/^[a-f0-9]{64}$/);
const unit = z.number().min(0).max(1);
const refs = z.array(z.string()).readonly().default([]);
const optionalText = z.string().nullable().default(null);

/** Pydantic `datetime`: a string, validated and returned in Pydantic's JSON form. */
export const DateTimeSchema = z.string().transform((text, ctx) => {
  try {
    return normalizeDateTime(text);
  } catch (error) {
    if (!(error instanceof DateTimeError)) throw error;
    ctx.addIssue({ code: 'custom', message: error.message });
    return z.NEVER;
  }
});
const nowDefault = DateTimeSchema.default(utcNow);

export const ArtifactIdentitySchema = z.strictObject({
  artifact_id: z.string(),
  project_id: z.string(),
  engagement_id: z.string(),
  artifact_type: z.string(),
  owner_department: z.string(),
}).readonly();

export const ArtifactVersionSchema = z.strictObject({
  artifact_version_id: z.string(),
  artifact_id: z.string(),
  version: z.number().int().min(1),
  parent_version_ref: optionalText,
  branch: z.string().default('main'),
  content_hash: hash64,
  semantic_fingerprint: optionalText,
  generation_mode: z.string().default('UNKNOWN'),
  dependency_version_refs: refs,
  validation_refs: refs,
  work_order_ref: z.string(),
  lifecycle: ArtifactLifecycleSchema.default('DRAFT'),
  created_at: nowDefault,
}).readonly();

export const ArtifactDependencySchema = z.strictObject({
  upstream_artifact_id: z.string(),
  downstream_artifact_id: z.string(),
  policy: DependencyPolicySchema,
}).readonly();

export const VersionDependencyBindingSchema = z.strictObject({
  output_artifact_version_id: z.string(),
  input_artifact_version_ids: z.array(z.string()).readonly(),
}).readonly();

export const ApprovalBindingSchema = z.strictObject({
  approval_id: z.string(),
  subject_type: z.enum(['ARTIFACT_VERSION', 'RELEASE_SUBJECT']),
  subject_ref: z.string(),
  subject_version_ref: z.string(),
  subject_hash: hash64,
  authority_ref: z.string(),
  policy_version: z.string(),
  status: ApprovalStatusSchema.default('PENDING'),
  reviewer_ref: optionalText,
  decision: optionalText,
  created_at: nowDefault,
  decided_at: DateTimeSchema.nullable().default(null),
  staled_at: DateTimeSchema.nullable().default(null),
  stale_reason: optionalText,
}).readonly();

export const ExecutionReceiptSchema = z.strictObject({
  operation_id: z.string(),
  work_order_id: z.string(),
  actor_role_id: z.string(),
  tool: z.string(),
  tool_contract_ref: z.string(),
  args_hash: hash64,
  target: z.string(),
  idempotency_key: z.string(),
  attempt: z.number().int().min(1).max(3),
  started_at: DateTimeSchema,
  ended_at: DateTimeSchema,
  returned_state: z.string(),
  result_ref: optionalText,
}).readonly();

/** Pydantic `Any` with no default: the key must be present (null is a value). */
const requiredAny = z.unknown().refine((value) => value !== undefined, 'Field required');

export const ObservationReceiptSchema = z.strictObject({
  operation_id: z.string(),
  target: z.string(),
  expected_postcondition: requiredAny,
  observed_postcondition: requiredAny,
  observation_method: z.string(),
  evidence_refs: refs,
  observed_at: nowDefault,
  matches: z.boolean(),
}).readonly();

export const FailureFingerprintSchema = z.strictObject({
  fingerprint: hash64,
  failure_class: z.string(),
  causal_node: z.string(),
  work_order_input_hash: z.string(),
  dependency_snapshot_hash: z.string(),
  tool_contract_hash: z.string(),
  environment_signature: z.string(),
  error_class: z.string(),
  error_code: optionalText,
  observed_postcondition: z.unknown().default(null),
}).readonly();

export const ProjectExecutionProjectionSchema = z.strictObject({
  project_id: z.string(),
  engagement_id: z.string(),
  mission_id: z.string(),
  current_phase: z.string(),
  causal_epoch: z.number().int().min(0),
  active_work_order_ids: refs,
  ready_work_order_ids: refs,
  blocked_work_order_ids: refs,
  awaiting_approval_ids: refs,
  artifact_head_refs: refs,
  stale_artifact_ids: refs,
  blockers: refs,
  proof_coverage: unit,
  updated_at: nowDefault,
  snapshot_hash: hash64,
}).readonly();

export const DispatchPermitSchema = z.strictObject({
  permit_id: z.string(),
  work_order_id: z.string(),
  project_snapshot_hash: hash64,
  causal_epoch: z.number().int().min(0),
  dependency_version_refs: refs,
  authority_refs: refs,
  approval_refs: refs,
  tool_contract_refs: refs,
  eligibility_policy_version: z.string(),
  issued_at: nowDefault,
}).readonly();

export const CompletionCriterionSchema = z.strictObject({
  criterion_ref: z.string(),
  mandatory: z.boolean().default(true),
  required_artifact_version_refs: refs,
  required_test_refs: refs,
  required_execution_receipt_refs: refs,
  required_observation_refs: refs,
  required_evidence_refs: refs,
  required_approval_refs: refs,
  required_metric_refs: refs,
}).readonly();

export const CompletionCriterionResultSchema = z.strictObject({
  criterion_ref: z.string(),
  status: CriterionStatusSchema,
  missing_refs: refs,
  stale_refs: refs,
}).readonly();

const score = z.union([unit, z.literal(NOT_MEASURED)]).default(NOT_MEASURED);

/** Completion verdict; `proof_coverage` comes from `proofCoverageFrom`, scores stay NOT_MEASURED until measured. */
export const CompletionEvaluationSchema = z.strictObject({
  terminal_candidate: z.enum(['COMPLETE', 'BLOCKED']),
  criteria: z.array(CompletionCriterionResultSchema).readonly(),
  proof_coverage: unit,
  evidence_score: score,
  quality_score: score,
  confidence: unit,
}).readonly();

export type ArtifactLifecycle = z.infer<typeof ArtifactLifecycleSchema>;
export type DependencyImpact = z.infer<typeof DependencyImpactSchema>;
export type DependencyPolicy = z.infer<typeof DependencyPolicySchema>;
export type SemanticChange = z.infer<typeof SemanticChangeSchema>;
export type ApprovalStatus = z.infer<typeof ApprovalStatusSchema>;
export type WorkOrderState = z.infer<typeof WorkOrderStateSchema>;
export type CriterionStatus = z.infer<typeof CriterionStatusSchema>;
export type ArtifactIdentity = z.infer<typeof ArtifactIdentitySchema>;
export type ArtifactVersion = z.infer<typeof ArtifactVersionSchema>;
export type ArtifactDependency = z.infer<typeof ArtifactDependencySchema>;
export type VersionDependencyBinding = z.infer<typeof VersionDependencyBindingSchema>;
export type ApprovalBinding = z.infer<typeof ApprovalBindingSchema>;
export type ExecutionReceipt = z.infer<typeof ExecutionReceiptSchema>;
export type ObservationReceipt = z.infer<typeof ObservationReceiptSchema>;
export type FailureFingerprint = z.infer<typeof FailureFingerprintSchema>;
export type ProjectExecutionProjection = z.infer<typeof ProjectExecutionProjectionSchema>;
export type DispatchPermit = z.infer<typeof DispatchPermitSchema>;
export type CompletionCriterion = z.infer<typeof CompletionCriterionSchema>;
export type CompletionCriterionResult = z.infer<typeof CompletionCriterionResultSchema>;
export type CompletionEvaluation = z.infer<typeof CompletionEvaluationSchema>;

/** Every schema by its Python class name. */
export const EXECUTION_SCHEMAS = {
  ArtifactIdentity: ArtifactIdentitySchema,
  ArtifactVersion: ArtifactVersionSchema,
  ArtifactDependency: ArtifactDependencySchema,
  VersionDependencyBinding: VersionDependencyBindingSchema,
  ApprovalBinding: ApprovalBindingSchema,
  ExecutionReceipt: ExecutionReceiptSchema,
  ObservationReceipt: ObservationReceiptSchema,
  FailureFingerprint: FailureFingerprintSchema,
  ProjectExecutionProjection: ProjectExecutionProjectionSchema,
  DispatchPermit: DispatchPermitSchema,
  CompletionCriterion: CompletionCriterionSchema,
  CompletionCriterionResult: CompletionCriterionResultSchema,
  CompletionEvaluation: CompletionEvaluationSchema,
} as const;

export type ExecutionModelName = keyof typeof EXECUTION_SCHEMAS;

/** Top-level fields Python declares `float`: their values dump (and hash) as floats even when integral. */
export const FLOAT_FIELDS: { readonly [K in ExecutionModelName]: readonly string[] } = {
  ArtifactIdentity: [], ArtifactVersion: [], ArtifactDependency: [], VersionDependencyBinding: [],
  ApprovalBinding: [], ExecutionReceipt: [], ObservationReceipt: [], FailureFingerprint: [],
  ProjectExecutionProjection: ['proof_coverage'], DispatchPermit: [], CompletionCriterion: [],
  CompletionCriterionResult: [],
  CompletionEvaluation: ['proof_coverage', 'evidence_score', 'quality_score', 'confidence'],
};

function isPlainObject(value: object): value is { readonly [key: string]: unknown } {
  const proto: unknown = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

/** Narrows parsed JSON-like data to a CanonicalValue; anything else is a CanonicalizationError. */
export function toCanonical(value: unknown): CanonicalValue {
  if (value === null || typeof value === 'boolean' || typeof value === 'number') return value;
  if (typeof value === 'string' || typeof value === 'bigint') return value;
  if (typeof value !== 'object') throw new CanonicalizationError(`unsupported canonical type: ${typeof value}`);
  if (value instanceof CanonicalFloat || value instanceof Uint8Array) return value;
  if (Array.isArray(value)) return value.map((item: unknown) => toCanonical(item));
  if (isPlainObject(value)) {
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, toCanonical(v)]));
  }
  throw new CanonicalizationError(`unsupported canonical type: ${value.constructor.name}`);
}

/** The value Python's `canonical_bytes(model)` encodes: the JSON dump, float fields as floats. */
export function canonicalRecord(model: ExecutionModelName, record: object): CanonicalValue {
  const floats = new Set(FLOAT_FIELDS[model]);
  const entries = Object.entries(record).map(([key, value]: [string, unknown]): [string, CanonicalValue] => {
    const asFloat = floats.has(key) && typeof value === 'number';
    return [key, asFloat ? new CanonicalFloat(value) : toCanonical(value)];
  });
  return Object.fromEntries(entries);
}

/** Python `canonical_hash(model)` for a record already parsed by its schema. */
export async function canonicalRecordHash(model: ExecutionModelName, record: object): Promise<string> {
  return canonicalHash(canonicalRecord(model, record));
}

/** Python `proof_coverage_from`: share of criteria satisfied; empty is 0, never a guess. */
export function proofCoverageFrom(criteria: readonly CompletionCriterionResult[]): number {
  if (criteria.length === 0) return 0;
  // ⚡ Bolt: Use zero-allocation reduce instead of .filter().length
  const satisfied = criteria.reduce((acc, item) => acc + (item.status === 'SATISFIED' ? 1 : 0), 0);
  return satisfied / criteria.length;
}
